<?php
function product_status_change($id,$target,$expected,$reason){
 if(!can_action('edit_product'))throw new Exception('Product editing access required.');
 if(!in_array((string)$target,['0','1'],true)||!in_array((string)$expected,['0','1'],true)||(int)$target===(int)$expected)throw new Exception('Invalid product status change.');$reason=process_reason($reason);
 return process_transaction(function()use($id,$target,$expected,$reason){$q=db()->prepare('SELECT * FROM products WHERE id=? FOR UPDATE');$q->execute([(int)$id]);$p=$q->fetch();if(!$p)throw new Exception('Product not found.');if((int)$p['active']!==(int)$expected)throw new Exception('Product status changed since you opened this form. Refresh Product Master.');
 if((int)$target===0){$stock=stock_row($id);if($stock['current']!==0||$stock['nonsellable']!==0||$stock['physical']!==0)throw new Exception('Cannot deactivate a product with remaining or negative stock. Resolve its stock through the normal inventory workflow first.');foreach(['Lazada','Shopee','TikTok'] as $pl)if(platform_qty($pl,$id)!==0)throw new Exception('All platform balances must be zero before deactivation.');
 $q=db()->prepare('SELECT COUNT(*) FROM borrowed_items WHERE product_id=? AND qty>returned_qty+converted_qty');$q->execute([$id]);if($q->fetchColumn())throw new Exception('Resolve outstanding borrowed items before deactivation.');
 $q=db()->prepare("SELECT COUNT(*) FROM inventory_count_lines l JOIN inventory_count_batches b ON b.id=l.batch_id WHERE l.product_id=? AND b.status NOT IN ('Applied','Cancelled','Reversed')");$q->execute([$id]);if($q->fetchColumn())throw new Exception('Complete or cancel the open inventory count before deactivation.');
 }
 db()->prepare('UPDATE products SET active=? WHERE id=?')->execute([(int)$target,(int)$id]);audit((int)$target?'Reactivate product':'Deactivate product','Product',$p['master_sku'],'Product ID '.$p['id'].'; '.$p['name'].'; '.((int)$expected?'Active':'Inactive').' → '.((int)$target?'Active':'Inactive').'; '.$reason.'; code, mapping and inventory history preserved.');return $p['master_sku'];
 });
}
function product_status_button($p){if(!can_action('edit_product'))return '';return '<button type="button" class="btn '.((int)$p['active']?'danger':'secondary').' sm product-status-button" data-product-id="'.(int)$p['id'].'" data-active="'.(int)$p['active'].'" data-product-name="'.e($p['name']).'" data-product-sku="'.e($p['master_sku']).'">'.((int)$p['active']?'Set Inactive':'Reactivate').'</button>';}
function product_status_dialog(){if(!can_action('edit_product'))return;echo '<dialog id="productStatusDialog"><form method="post" action="actions.php" class="modal-card stack" data-confirm="Change this product status? Its item code, mappings and history will be preserved."><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="set_product_status"><input type="hidden" name="return" value="products"><input type="hidden" name="product_id" id="ps_product"><input type="hidden" name="expected_active" id="ps_expected"><input type="hidden" name="active" id="ps_active"><div class="modal-head"><h3 id="ps_title">Product Status</h3><button type="button" onclick="this.closest(\'dialog\').close()" aria-label="Close">×</button></div><p id="ps_description"></p><p>Inactive products are excluded from new product selections. Their item codes, platform mappings and history are retained. Remaining/negative stock, outstanding borrowed items or an open count must be resolved first.</p><label>Reason<textarea name="reason" minlength="3" maxlength="2000" required></textarea></label><div class="modal-actions"><button type="button" class="btn ghost" onclick="this.closest(\'dialog\').close()">Cancel</button><button class="btn primary" id="ps_submit">Confirm Status Change</button></div></form></dialog><script src="assets/product_status.js"></script>';}
